//! Port of `pkg/oniguruma/c.zig`.
//!
//! STATUS: ported
//!
//! The Zig package translate-c's `oniguruma.h`. The Rust equivalent is
//! `c_bindings.rs`, generated by rust-bindgen 0.73 from the same header of
//! the system oniguruma (allowlist `onig_.*|Onig.*|ONIG.*|OnigEnc.*`, macro
//! constants typed `i32`) and linked via pkg-config in `build.rs`.
//!
//! Zig's `c.zig` wraps the translation in a `c` declaration, so Zig code
//! spells it `oniguruma.c.c.onig_new`; in Rust it is `oniguruma::c::onig_new`.
//! The `ONIG_ENCODING_*`/`ONIG_SYNTAX_*` address-of macros are available as
//! `types::Encoding::*()`/`types::Syntax::*()`.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all
)]

include!("c_bindings.rs");
